bool RelationStatisticsHelper::IsSubstringMatchPredicate(const Expression &expr) {
	switch (expr.GetExpressionClass()) {
	case ExpressionClass::BOUND_CONJUNCTION: {
		if (expr.GetExpressionType() != ExpressionType::CONJUNCTION_AND) {
			return false;
		}
		auto &conj = expr.Cast<BoundConjunctionExpression>();
		for (auto &child : conj.children) {
			if (IsSubstringMatchPredicate(*child)) {
				return true;
			}
		}
		return false;
	}
	case ExpressionClass::BOUND_FUNCTION: {
		auto &func = expr.Cast<BoundFunctionExpression>();
		if (func.children.size() < 2) {
			return false;
		}
		auto &name = func.function.name;
		if (name == "contains") {
			auto &needle = *func.children[1];
			if (needle.GetExpressionClass() != ExpressionClass::BOUND_CONSTANT) {
				return false;
			}
			auto &value = needle.Cast<BoundConstantExpression>().value;
			return !value.IsNull() && value.type().id() == LogicalTypeId::VARCHAR &&
			       !StringValue::Get(value).empty();
		}
		if (name == "~~" || name == "like_escape") {
			return IsSubstringLikePattern(*func.children[1]);
		}
		return false;
	}
	default:
		return false;
	}
}

bool RelationStatisticsHelper::IsSubstringMatchFilter(const TableFilter &filter) {
	switch (filter.filter_type) {
	case TableFilterType::EXPRESSION_FILTER:
		return IsSubstringMatchPredicate(*filter.Cast<ExpressionFilter>().expr);
	case TableFilterType::CONJUNCTION_AND: {
		auto &conj = filter.Cast<ConjunctionAndFilter>();
		for (auto &child : conj.child_filters) {
			if (IsSubstringMatchFilter(*child)) {
				return true;
			}
		}
		return false;
	}
	default:
		return false;
	}
}

double RelationStatisticsHelper::GetDefaultSelectivity(const vector<unique_ptr<Expression>> &expressions) {
	for (auto &expr : expressions) {
		if (IsSubstringMatchPredicate(*expr)) {
			return SUBSTRING_MATCH_SELECTIVITY;
		}
	}
	return DEFAULT_SELECTIVITY;
}

